{{include reference="ReleaseNotes.Code.Change.ChangeDisplayerVelocityMacros"/}}
{{velocity}} ## Inputs: ## - $changeItems ## - $displayEditLink (% class='container col-xs-12' %)((( #foreach ($item in $changeItems) (% class='row' %)((( (% class='col-xs-6' %)((( #set ($changeDoc = $xwiki.getDocument($item)) #set ($changeObject = $changeDoc.getObject("ReleaseNotes.Code.Change.ChangeClass")) #displayScreenshots($changeObject, true, false) ))) (% class="col-xs-6" %)((( #generateDisplayEditLink($displayEditLink, $changeDoc) #set ($title = $services.rendering.escape("$!changeObject.getValue('title')", 'xwiki/2.1')) ## The title of a change is optional, so a change is only given a section of its own when it has one: a heading ## holding no text at all would leave an empty section in the release note, and an empty entry in the table of ## contents the release note template displays. The edit link then follows the summary, the only thing that ## displays such a change. #if ($title != '') === $title${displayEditLinkMarkup}===
#end ## Display the summary through the change document, so that its rich text is rendered in the context of that ## document rather than of this displayer, the way the change's own page renders it. $changeDoc.display('summary', 'view', $changeObject)#if ($title == '')${displayEditLinkMarkup}#end #set ($description = $changeObject.getValue('description')) #if ("$!description" != '') [[${moreDetailsLabel}>>doc:$changeDoc.documentReference]] #end ))) )))
#end ))) {{/velocity}}
